def defaultObj = logic.param('Default').getReal()
def docs = logic.param('doclist').getReal() ?: []

// 规范化查询片段（去除 .md 后缀、空白）
def normalizeQueryPart = { text ->
    if (text == null) {
        return null
    }
    def value = text.trim()
    if (value.toLowerCase().endsWith('.md')) {
        value = value.substring(0, value.length() - 3)
    }
    return value.trim()
}

// 按 / 或 \ 拆分查询词
def rawQuery = defaultObj?.get('query')?.toString()
def queryParts = []
if (rawQuery != null && rawQuery.trim().length() > 0) {
    queryParts = rawQuery
        .split("[/\\\\]+")
        .collect { normalizeQueryPart(it) }
        .findAll { it != null && it.length() > 0 }
}
def isPathQuery = queryParts.size() > 1

// 由文档 path 字段构建树节点（目录/文件），node_key 为完整路径前缀，文件节点补充 id、size
def treeNodes = []
def nodeKeySet = new LinkedHashSet()
docs.each { doc ->
    def path = doc.get('path')
    if (path == null) {
        return
    }
    def segments = path.toString().trim().split('[/\\\\]+').findAll { it.trim().length() > 0 }
    if (segments.size() == 0) {
        return
    }
    def pathParts = []
    segments.eachWithIndex { seg, idx ->
        pathParts.add(seg)
        def nodeKey = pathParts.join('/')
        if (!nodeKeySet.contains(nodeKey)) {
            nodeKeySet.add(nodeKey)
            def parentKey = pathParts.size() > 1 ? pathParts.subList(0, pathParts.size() - 1).join('/') : null
            def isFile = (idx == segments.size() - 1)
            treeNodes.add([
                node_key   : nodeKey,
                parent_key : parentKey,
                name       : seg,
                type       : isFile ? 'file' : 'dir',
                match_text : seg,
                id         : isFile ? doc.get('id') : null,
                size       : isFile ? doc.get('size') : null
            ])
        }
    }
}

// 同级排序：目录优先，再按名称
treeNodes.sort { a, b ->
    if (a.type != b.type) {
        return a.type == 'dir' ? -1 : 1
    }
    return a.name <=> b.name
}

def resultNodes = treeNodes
if (queryParts.size() > 0) {
    def compilePattern = { text ->
        return java.util.regex.Pattern.compile(
            java.util.regex.Pattern.quote(text),
            java.util.regex.Pattern.CASE_INSENSITIVE | java.util.regex.Pattern.UNICODE_CASE
        )
    }
    def queryPatterns = queryParts.collect { compilePattern(it) }
    def nodeMap = [:]
    def childrenMap = [:].withDefault { [] }
    treeNodes.each { node ->
        nodeMap[node.node_key] = node
        childrenMap[node.parent_key].add(node)
    }
    def visibleKeys = new LinkedHashSet()
    def addAncestors
    addAncestors = { node ->
        def current = node
        while (current != null && current.parent_key != null) {
            def parent = nodeMap[current.parent_key]
            if (parent == null) {
                break
            }
            visibleKeys.add(parent.node_key)
            current = parent
        }
    }
    def addSubTree
    addSubTree = { node ->
        if (node == null) {
            return
        }
        visibleKeys.add(node.node_key)
        childrenMap[node.node_key].each { child ->
            addSubTree(child)
        }
    }
    def getNodePath = { node ->
        def path = []
        def current = node
        while (current != null) {
            path.add(0, current)
            current = current.parent_key != null ? nodeMap[current.parent_key] : null
        }
        return path
    }
    def matchText = { pattern, text ->
        if (text == null) {
            return false
        }
        return pattern.matcher(text.toString()).find()
    }
    if (isPathQuery) {
        // 路径查询：按完整路径尾部逐级匹配
        treeNodes.each { node ->
            def nodePath = getNodePath(node)
            if (nodePath.size() >= queryPatterns.size()) {
                def fromIndex = nodePath.size() - queryPatterns.size()
                def tailPath = nodePath.subList(fromIndex, nodePath.size())
                def matched = true
                queryPatterns.eachWithIndex { pattern, index ->
                    def pathNode = tailPath[index]
                    def pathText = pathNode.name ?: ''
                    if (!matchText(pattern, pathText)) {
                        matched = false
                    }
                }
                if (matched) {
                    visibleKeys.add(node.node_key)
                    addAncestors(node)
                    if (node.type == 'dir') {
                        addSubTree(node)
                    }
                }
            }
        }
    } else {
        // 关键字查询：匹配节点名称
        def pattern = queryPatterns[0]
        treeNodes.each { node ->
            def matched = matchText(pattern, node.match_text ?: '')
            if (matched) {
                visibleKeys.add(node.node_key)
                addAncestors(node)
                if (node.type == 'dir') {
                    addSubTree(node)
                }
            }
        }
    }
    resultNodes = treeNodes.findAll { visibleKeys.contains(it.node_key) }
}

// 输出树形文本（文件节点附带 id、size）
def outputChildrenMap = [:].withDefault { [] }
resultNodes.each { node ->
    outputChildrenMap[node.parent_key].add(node)
}
def buildTree
buildTree = { parentKey, prefix ->
    def result = []
    def children = outputChildrenMap[parentKey]
    children.eachWithIndex { item, idx ->
        def isLast = idx == children.size() - 1
        def connector = isLast ? '└── ' : '├── '
        def typeTag = item.type == 'dir' ? '[目录] ' : ''
        def extraInfo = ''
        if (item.type == 'file') {
            extraInfo = "  (id: ${item.id}, size: ${item.size})"
        }
        result.add(prefix + connector + typeTag + item.name + extraInfo)
        def childPrefix = prefix + (isLast ? '    ' : '│   ')
        result.addAll(buildTree(item.node_key, childPrefix))
    }
    return result
}
def treeLines = buildTree(null, '')
logic.param('resultJson').bind(treeLines)
